        /// <summary>
        /// Serialize instances of meta-model classes to XML.
        /// </summary>
        /// <example>
        /// Here is an example how to serialize an instance of IElement:
        /// <code>
        /// var anInstance = new Aas.IElement(
        ///     /* ... some constructor arguments ... */
        /// );
        /// var writer = new System.Xml.XmlWriter( /* some arguments */ );
        /// Serialize.To(
        ///     anInstance,
        ///     writer);
        /// </code>
        /// </example>
        public static class Serialize
        {
            /// <summary>
            /// Serialize an instance of the meta-model to XML.
            /// </summary>
            /// <exception cref="SerializationException">
            /// Thrown when a value within <paramref name="that" /> instance can not be
            /// represented in XML
            /// </exception>
            public static void To(
                Aas.IClass that,
                Xml.XmlWriter writer)
